class Solution:
    def equalSubstring(self, s: str, t: str, maxCost: int) -> int:
        left = 0
        curr_cost = 0
        max_len = 0
        for right in range(len(s)):
            curr_cost += abs(ord(s[right]) - ord(t[right]))
            while curr_cost > maxCost:
                curr_cost -= abs(ord(s[left]) - ord(t[left]))
                left += 1
            max_len = max(max_len, right - left + 1)
        return max_len

class Solution {
public:
    int equalSubstring(string s, string t, int maxCost) {
        int left = 0, curr_cost = 0, max_len = 0;
        for (int right = 0; right < (int)s.length(); right++) {
            curr_cost += abs(s[right] - t[right]);
            while (curr_cost > maxCost) {
                curr_cost -= abs(s[left] - t[left]);
                left++;
            }
            max_len = max(max_len, right - left + 1);
        }
        return max_len;
    }
};

class Solution {
    public int equalSubstring(String s, String t, int maxCost) {
        int left = 0, curr_cost = 0, max_len = 0;
        for (int right = 0; right < s.length(); right++) {
            curr_cost += Math.abs(s.charAt(right) - t.charAt(right));
            while (curr_cost > maxCost) {
                curr_cost -= Math.abs(s.charAt(left) - t.charAt(left));
                left++;
            }
            max_len = Math.max(max_len, right - left + 1);
        }
        return max_len;
    }
}

var equalSubstring = function(s, t, maxCost) {
    let left = 0, curr_cost = 0, max_len = 0;
    for (let right = 0; right < s.length; right++) {
        curr_cost += Math.abs(s.charCodeAt(right) - t.charCodeAt(right));
        while (curr_cost > maxCost) {
            curr_cost -= Math.abs(s.charCodeAt(left) - t.charCodeAt(left));
            left++;
        }
        max_len = Math.max(max_len, right - left + 1);
    }
    return max_len;
};
